});"

Execute: $ cd /company/repos/cosmon-game && node -e "
import('/usr/local/lib/node_modules/playwright/index.mjs').then(async ({chromium}) => {
  const b = await chromium.launch({executablePath:'/usr/bin/chromium', headless:true, args:['--no-sandbox','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swangle-shader']});
  const p = await b.newPage();
  const errs = [];
  p.on('pageerror', e => errs.push(e.message));
  await p.goto('http://127.0.0.1:8231/index.html');
  await p.waitForFunction(() => window.__game && document.querySelector('#intro'));
  await p.click('.starter-card:nth-child(1) .sc-btn');
  await p.waitForFunction(() => window.__game.mode === 'play');
  const res = await p.evaluate(async () => {
    const g = window.__game;
    const THREE = window.__game.scene.background; // not needed
    const center = { clone(){ return {x:10,y:0,z:10}; } }; // duck-typed Vector3
    let resolved = null;
    g._beginBattle({ speciesId: 'crystawk', level: 6, center, allowBond: false,
        enemyScale: 1.6, enemyTint: 0x5e4bff, enemyName: 'Corrupted Crystawk',
        onResolved: (result, payload) => { resolved = { result, xp: payload.xpGained }; } });
    const out = {};
    out.modeBattle = g.mode === 'battle';
    out.enemyName = g.battle.enemy.species.name;
    out.enemyScale = g.battle.enemy.scaleMult;
    // bond must be refused
    g.battle.press('KeyB');
    out.bondRefused = g.battle.phase === 'fight' && !g.battle.done;
    // defeat the foe via direct damage
    for (let i = 0; i < 200 && !g.battle.done; i++) {
      g.battle._dealDamage(g.battle.active(), g.battle.enemy, { power: 40, element: 'Flame', kind: 'melee' });
      await new Promise(r => setTimeout(r, 10));
    }
    await new Promise(r => setTimeout(r, 300));
    out.resolved = resolved;
    out.modePlay = g.mode === 'play';
    out.battleNull = g.battle === null;
    out.errors = 0;
    return out;
  });
  console.log(JSON.stringify(res));
  console.log('pageerrors:', errs.length ? errs : 'none');
  await b.close();
});"

